    'tour.block.recepcion.tarimas.title': '托盘分类',
    'tour.block.recepcion.tarimas.desc': '在订单验收页面，可通过顶部按钮启用"托盘分类"功能。系统将根据编码自动将箱子归入虚拟托盘，方便实物清点。',
    'tour.block.inventario.label': '库存',
    'tour.block.inventario.intro.title': '库存 — 扫描与管控',
    'tour.block.inventario.intro.desc': '库存模块支持两种扫描方式：统一模式（所有箱子归入同一托盘）和分类模式（系统按编码自动分组至不同托盘）。',
    'tour.block.inventario.rastreo.title': '追踪',
    'tour.block.inventario.rastreo.desc': '"追踪"子模块记录并跟踪需要定位或主动搜索的箱子。在此创建追踪单并监控进度。',
    'tour.block.inventario.quicksearch.title': '快速搜索',
    'tour.block.inventario.quicksearch.desc': '快速搜索按钮可查询任意编码，并汇总展示其在系统所有相关记录中的信息。',
    'tour.block.devoluciones.label': '退货管理',
    'tour.block.devoluciones.intro.title': '退货全流程管理',
    'tour.block.devoluciones.intro.desc': '退货模块管理退货全流程：入库（登记收到的退货）、库存（管理退货商品）和出库（退回供应商或最终处置）。',
    'tour.block.anormalidades.label': '异常管理',
    'tour.block.anormalidades.intro.title': '异常管理',
    'tour.block.anormalidades.intro.desc': '异常模块用于记录操作事故、生成质量仪表盘报告，并记录持续改进措施以跟踪和解决问题。',
    'tour.block.admin.label': '系统管理',
    'tour.block.admin.intro.title': '系统管理',
    'tour.block.admin.intro.desc': '在系统管理模块中管理团队用户、角色和权限、租户配置及系统集成。',
    // ── Tour — nuevos pasos ───────────────────────────────────────────────
    'tour.block.dropscan.canales.title': '渠道与配置',
    'tour.block.dropscan.canales.desc': '渠道在 DropScan <strong>配置</strong>中创建。在此定义快递公司、分发渠道（按目的地或服务类型）及内部操作员。每次扫描会话绑定到特定渠道——未配置渠道则无法启动会话。',
    'tour.block.inventario.wmscfg.title': '必要配置：WMS 库存数据库连接',
    'tour.block.inventario.wmscfg.desc': '库存模块需连接真实 WMS 的<strong>库存数据库</strong>（Google Sheets 或其他来源）。在侧边栏<strong>连接</strong>中配置。未连接时系统无法验证箱子是否存在于 WMS 库存中。',
    'tour.block.inventario.clasificacion.title': '托盘分类方式',
    'tour.block.inventario.clasificacion.desc': '扫描模块支持两种模式：<strong>统一</strong>（所有箱子归入同一托盘）；<strong>分类</strong>（系统按编码自动将箱子分入不同托盘）。切换为分类模式后，侧面板实时显示各分类组的数量，并可按组确认发送。',
    'tour.block.inventario.ubicaciones.title': '仓库库位',
    'tour.block.inventario.ubicaciones.desc': '启用分类模式前，仓库<strong>库位必须已从 WMS 目录导入</strong>系统。未导入库位时，系统无法为已分类的托盘分配或验证目标区域。请在开始扫描前在"管理"中导入库位。',
    'tour.block.surtido.wmscfg.title': '必要配置：WMS 出库订单数据库',
    'tour.block.surtido.wmscfg.desc': '拣货和出库模块需连接真实 WMS 的<strong>出库订单数据库</strong>（Google Sheets）。未配置集成时将无法加载拣货订单。请在侧边栏<strong>连接</strong>中配置数据源后再操作此模块。',
    'tour.block.surtido.surtidores_cfg.title': '拣货员管理',
    'tour.block.surtido.surtidores_cfg.desc': '分配订单前，通过订单视图中的<strong>拣货员</strong>按钮注册操作人员。可添加、编辑或停用拣货员。每笔订单可分配给一名或多名拣货员，精确追踪各人完成进度。',
    'tour.block.surtido.print.title': '打印叉车操作员库位清单',
    'tour.block.surtido.print.desc': '在订单列表中可打印分配给<strong>两位叉车操作员</strong>的库位清单。该报表指示操作员需要前往哪些仓库库位提取货物，便于两人同时作业而不产生区域冲突。',
    'tour.block.despacho.wmscfg.title': '必要配置：WMS 出库订单数据库',
    'tour.block.despacho.wmscfg.desc': '出库发货模块同样需连接真实 WMS 的<strong>出库订单数据库</strong>（Google Sheets），与拣货模块共享同一数据源。未配置集成时将无法显示发货订单。请在侧边栏<strong>连接</strong>中验证配置。',
    'tour.block.despacho.catalogs_cfg.title': '车辆与司机目录',
    'tour.block.despacho.catalogs_cfg.desc': '创建发货单前，在订单视图对应按钮中注册<strong>司机</strong>（姓名、驾照）和<strong>运输车辆</strong>（车牌、类型：货车、厢式车、拖车等）。未设置目录则无法为发货单分配运输资源。',
    'tour.block.despacho.print.title': '打印：发货日程与发货单',
    'tour.block.despacho.print.desc': '在<strong>出库发货→订单</strong>中可打印<strong>发货日程</strong>，显示当日每笔订单的计划时间和目的地，便于路线规划与协调。在<strong>出库发货→发货单</strong>中打印<strong>发货单</strong>：包含订单关系、日期/时间、司机、车辆和收件人的正式文件，随货物交给运输司机。',
    'tour.block.inventario.rastreo_cfg.title': '追踪原因管理',
    'tour.block.inventario.rastreo_cfg.desc': '在<strong>追踪</strong>子模块中可配置追踪原因：需要主动定位箱子的原因（如：缺货、位置错误、紧急等）。创建追踪单前先定义这些原因类别，以保持分类一致性并便于后续分析。',
    'tour.module_chip': '模块 {{n}} / {{total}}',
