    // Onboarding tour
    'tour.welcome.title': 'Bienvenido a Kirion WMS',
    'tour.welcome.description': 'Bienvenido a <strong>{tenant}</strong>. este recorrido interactivo te guiará por los módulos principales del sistema para que puedas comenzar a operar rápidamente.',
    'tour.sidebar.title': 'Menú de Navegación',
    'tour.sidebar.description': 'La barra lateral izquierda contiene el acceso a todos los módulos del sistema. haz clic en cualquier ítem para navegar.',
    'tour.config.title': 'Configuración Inicial',
    'tour.config.description': 'Antes de escanear, configura aquí las empresas de paquetería, canales y escaneadores. puedes usar cuentas de usuario o crear escaneadores internos para control de personal — ideales cuando solo necesitas permisos de ver y crear, sin modificar ni eliminar.',
    'tour.config_empresas.title': 'Empresas de Paquetería',
    'tour.config_empresas.description': 'Registra las empresas paqueteras (dhl, fedex, etc.) y sus canales de operación. las sesiones de escaneo quedan vinculadas a empresa y canal específicos.',
    'tour.config_canales.title': 'Canales de Distribución',
    'tour.config_canales.description': 'Los canales agrupan las guías por destino o tipo de servicio. cada canal pertenece a una empresa y las sesiones de escaneo se vinculan a empresa y canal específicos.',
    'tour.config_operadores.title': 'Gestión de Escaneadores',
    'tour.config_operadores.description': 'Registra y administra a los operadores que escanean en almacén. los escaneadores internos se autentican con PIN, sin necesidad de cuenta completa en el sistema.',
    'tour.dashboard_kpis.title': 'Resumen del Día',
    'tour.dashboard_kpis.description': 'Aquí ves los indicadores clave en tiempo real: total de guías procesadas, tarimas en proceso, completadas, canceladas y alertas de duplicados.',
    'tour.dashboard_sesiones.title': 'Sesiones Activas en Tiempo Real',
    'tour.dashboard_sesiones.description': 'Muestra los operadores que están escaneando ahora mismo, con su empresa, canal y guías acumuladas. te permite supervisar la operación al instante.',
    'tour.historial_tabla.title': 'Tabla de Tarimas',
    'tour.historial_tabla.description': 'Haz clic en cualquier fila para ver el detalle: guías escaneadas, historial de operaciones y opciones para cambiar el estado o exportar la información.',
    'tour.escaneo.title': 'Módulo de Escaneo',
    'tour.escaneo.description': 'Aquí inicias sesiones de escaneo de guías. el sistema crea una tarima automáticamente y registra todas las guías escaneadas.',
    'tour.iniciar_sesion.title': 'Iniciar Sesión de Escaneo',
    'tour.iniciar_sesion.description': 'Usa el botón de inicio de sesión para comenzar. con escaneadores internos aparece un modal de PIN; con cuenta de usuario el sistema autentica automáticamente.',
    'tour.tarimas.title': 'Historial de Tarimas',
    'tour.tarimas.description': 'Aquí consultas todas las tarimas creadas, el historial de guías y el estado de cada operación. puedes filtrar, exportar y gestionar estados.',
    'tour.folios.title': 'Folios de Entrega',
    'tour.folios.description': 'Para generar un folio, haz clic en "nuevo folio", selecciona la empresa y los canales. al aplicar los filtros, el sistema carga automáticamente las tarimas y guías disponibles con un resumen. al confirmar, se genera el folio oficial para imprimirlo y entregar las guías.',
    'tour.reportes.title': 'Reportes',
    'tour.reportes.description': 'Exporta datos de guías, consulta estadísticas y analiza el volumen de operación por fecha, empresa, canal y más.',
