    'tour.block.dropscan.folios.title': 'Folios',
    'tour.block.dropscan.folios.desc': 'Los Folios concentran tarimas y guías para una entrega formal. Crea un folio, selecciona empresa y canales, aplica filtros y confirma para generar el documento de entrega.',
    'tour.block.surtido.label': 'Surtido',
