    'tour.block.surtido.intro.desc': 'El módulo de Surtido gestiona el control de órdenes de surtido, la asignación de surtidores a cada orden, y el proceso completo de validación de cajas con sus registros de progreso y seguimiento.',
    'tour.block.surtido.surtidores.title': 'Gestión de Surtidores',
